parameters.item/LastFailureMessage:
@if(
  or(
    equals(variables('AuditOutcome'), 'Succeeded'),
    equals(variables('AuditOutcome'), 'Warning')
  ),
  first(body('GET_StatusRow_Agent_01')?['value'])?['LastFailureMessage'],
  concat(
    'Agent 1 completed with failure. AuditOutcome=',
    variables('AuditOutcome'),
    ' | DomainsExtracted=',
    string(length(variables('DomainArray')))
  )
)

parameters.item/LastWarningMessage:
@if(
  equals(variables('AuditOutcome'), 'Warning'),
  concat(
    'Agent 1 completed with warnings. DomainsExtracted=',
    string(length(variables('DomainArray')))
  ),
  first(body('GET_StatusRow_Agent_01')?['value'])?['LastWarningMessage']
)

parameters.item/LastFailureMessage:
@if(
  or(
    equals(variables('AuditOutcome'), 'Succeeded'),
    equals(variables('AuditOutcome'), 'Warning')
  ),
  first(body('GET_StatusRow_ExternalDomains')?['value'])?['LastFailureMessage'],
  concat(
    'External domains file was not updated successfully. AuditOutcome=',
    variables('AuditOutcome'),
    ' | DomainsExtracted=',
    string(length(variables('DomainArray')))
  )
)

parameters.item/LastWarningMessage:
@if(
  equals(variables('AuditOutcome'), 'Warning'),
  concat(
    'External domains update completed with warnings. DomainsExtracted=',
    string(length(variables('DomainArray')))
  ),
  first(body('GET_StatusRow_ExternalDomains')?['value'])?['LastWarningMessage']
)

inputs.select:
@concat(
  ',',
  '"',
  replace(coalesce(item()?['Title'], ''), '"', concat(decodeUriComponent('%5C'), '"')),
  '":"',
  replace(
    replace(
      replace(
        replace(
          coalesce(
            if(
              equals(variables('OperationMode'), 'PROD_NODMP'),
              item()?['Value_PROD_NODMP'],
              if(
                equals(variables('OperationMode'), 'PROD_DMP'),
                item()?['Value_x002d_PROD_x0028_DMP_x0029'],
                if(
                  equals(variables('OperationMode'), 'SIMU_NODMP'),
                  coalesce(item()?['Value_x002d_SIMU_x0028_NODMP_x0029'], item()?['Value_x002d_SIMU_x0028_NODMP_x00']),
                  item()?['Value_x002d_SIMU_x0028_DMP_x0029']
                )
              )
            ),
            ''
          ),
          decodeUriComponent('%5C'),
          concat(decodeUriComponent('%5C'), decodeUriComponent('%5C'))
        ),
        '"',
        concat(decodeUriComponent('%5C'), '"')
      ),
      decodeUriComponent('%0D'),
      ''
    ),
    decodeUriComponent('%0A'),
    concat(decodeUriComponent('%5C'), 'n')
  ),
  '"'
)
